113	static const char *
114	process_filter_opt(url_mapping *mp, const BUILD_TABLE_INFO *bti, char *errStrBuf, int errStrBufSize)
115	{
116	  acl_filter_rule *rp, **rpp;
117	  const char      *errStr = nullptr;
118	
119	  if (unlikely(!mp || !bti || !errStrBuf || errStrBufSize <= 0)) {
120	    Dbg(dbg_ctl_url_rewrite, "[process_filter_opt] Invalid argument(s)");
121	    return "[process_filter_opt] Invalid argument(s)";
122	  }
123	  // ACLs are processed in this order:
124	  // 1. A remap.config ACL line for an individual remap rule.
125	  // 2. All named ACLs in remap.config.
126	  // 3. Rules as specified in ip_allow.yaml.
127	  if (!errStr && (bti->remap_optflg & REMAP_OPTFLG_ALL_FILTERS) != 0) {
128	    Dbg(dbg_ctl_url_rewrite, "[process_filter_opt] Add per remap filter");
129	    for (rpp = &mp->filter; *rpp; rpp = &((*rpp)->next)) {
130	      ;
131	    }
132	    errStr = remap_validate_filter_args(rpp, bti->argv, bti->argc, errStrBuf, errStrBufSize, bti->behavior_policy);
133	  }
134	
135	  for (rp = bti->rules_list; rp; rp = rp->next) {
136	    for (rpp = &mp->filter; *rpp; rpp = &((*rpp)->next)) {
137	      ;
138	    }
139	    if (rp->active_queue_flag) {
140	      Dbg(dbg_ctl_url_rewrite, "[process_filter_opt] Add active main filter \"%s\" (argc=%d)",
141	          rp->filter_name ? rp->filter_name : "<nullptr>", rp->argc);
142	      for (rpp = &mp->filter; *rpp; rpp = &((*rpp)->next)) {
143	        ;
144	      }
145	      if ((errStr = remap_validate_filter_args(rpp, rp->argv, rp->argc, errStrBuf, errStrBufSize, bti->behavior_policy)) !=
146	          nullptr) {
147	        break;
148	      }
149	    }
150	  }
151	
152	  // Set the ip allow flag for this rule to the current ip allow flag state
153	  mp->ip_allow_check_enabled_p = bti->ip_allow_check_enabled_p;
154	
155	  return errStr;
156	}
