35	// ===============================================================================
36	// ACL like filtering defs (per one remap rule)
37	
38	static int const ACL_FILTER_MAX_SRC_IP = 128;
39	static int const ACL_FILTER_MAX_IN_IP  = 8;
40	static int const ACL_FILTER_MAX_ARGV   = 512;
41	
42	struct src_ip_info_t {
43	  IpAddr start;               ///< Minimum value in range.
44	  IpAddr end;                 ///< Maximum value in range.
45	  bool   invert;              ///< Should we "invert" the meaning of this IP range ("not in range")
46	  bool   match_all_addresses; ///< This rule should match all IP addresses.
47	
48	  void
49	  reset()
50	  {
51	    start.invalidate();
52	    end.invalidate();
53	    invert              = false;
54	    match_all_addresses = false;
55	  }
56	
57	  /// @return @c true if @a ip is inside @a this range.
58	  bool
59	  contains(IpEndpoint const &ip) const
60	  {
61	    if (match_all_addresses) {
62	      return true;
63	    }
64	    IpAddr addr{ip};
65	    return addr.cmp(start) >= 0 && addr.cmp(end) <= 0;
66	  }
67	};
68	
69	struct src_ip_category_info_t {
70	  std::string category;       ///< The IP category for this remap rule.
71	  bool        invert = false; ///< Should we "invert" the meaning of these IP categories ("not in categories")
72	
73	  void
74	  reset()
75	  {
76	    category.clear();
77	    invert = false;
78	  }
79	
80	  /// @return @c true if @a ip is inside @a this categories.
81	  bool
82	  contains(IpEndpoint const &ip) const
83	  {
84	    return ask_ip_allow_about_category(category, swoc::IPAddr{ip});
85	  }
86	
87	private:
88	  bool ask_ip_allow_about_category(std::string const &category, swoc::IPAddr const &addr) const;
89	};
