94	class acl_filter_rule
95	{
96	private:
97	  void reset();
98	
99	public:
100	  acl_filter_rule *next        = nullptr;
101	  char            *filter_name = nullptr; // optional filter name
102	  unsigned int     allow_flag : 1,        // action allow or add_allow (1); or deny or add_deny (0)
103	    add_flag                  : 1,        // add_allow/add_deny (1) or allow/deny (0)
104	    src_ip_valid              : 1,        // src_ip (client's src IP) range is specified and valid
105	    src_ip_category_valid     : 1,        // src_ip_category (client's src IP category) is specified and valid
106	    in_ip_valid               : 1,        // in_ip (client's dest IP) range is specified and valid
107	    active_queue_flag         : 1,        // filter is in active state (used by .useflt directive)
108	    internal                  : 1;        // filter internal HTTP requests
109	
110	  // we need arguments as string array for directive processing
111	  int   argc = 0;                  // argument counter (only for filter defs)
112	  char *argv[ACL_FILTER_MAX_ARGV]; // argument strings (only for filter defs)
113	
114	  // methods
115	  bool              method_restriction_enabled;
116	  std::vector<bool> standard_method_lookup;
117	
118	  using MethodMap = std::set<std::string>;
119	  MethodMap nonstandard_methods;
120	
121	  // src_ip
122	  int           src_ip_cnt; // how many valid src_ip rules we have
123	  src_ip_info_t src_ip_array[ACL_FILTER_MAX_SRC_IP];
124	
125	  int                    src_ip_category_cnt = 0; // how many valid src_ip rules we have
126	  src_ip_category_info_t src_ip_category_array[ACL_FILTER_MAX_SRC_IP];
127	
128	  // in_ip
129	  int           in_ip_cnt; // how many valid dest_ip rules we have
130	  src_ip_info_t in_ip_array[ACL_FILTER_MAX_IN_IP];
131	
132	  acl_filter_rule();
133	  ~acl_filter_rule();
134	  void name(const char *_name = nullptr);
135	  int  add_argv(int _argc, char *_argv[]);
136	  void print();
137	
138	  /** Return a description of the action.
139	   *
140	   * @return "allow", "add_allow", "deny", or "add_deny", as appropriate.
141	   */
142	  char const *get_action_description() const;
143	
144	  static acl_filter_rule *find_byname(acl_filter_rule *list, const char *name);
145	  static void             delete_byname(acl_filter_rule **list, const char *name);
146	  static void             requeue_in_active_list(acl_filter_rule **list, acl_filter_rule *rp);
147	  static void             requeue_in_passive_list(acl_filter_rule **list, acl_filter_rule *rp);
148	};
