43	void
44	acl_filter_rule::reset()
45	{
46	  int i;
47	  for (i = (argc = 0); i < ACL_FILTER_MAX_ARGV; i++) {
48	    argv[i] = static_cast<char *>(ats_free_null(argv[i]));
49	  }
50	  method_restriction_enabled = false;
51	  for (i = 0; i < HTTP_WKSIDX_METHODS_CNT; i++) {
52	    standard_method_lookup[i] = false;
53	  }
54	  nonstandard_methods.clear();
55	  for (i = (src_ip_cnt = 0); i < ACL_FILTER_MAX_SRC_IP; i++) {
56	    src_ip_array[i].reset();
57	  }
58	  src_ip_category_valid = 0;
59	  for (i = (src_ip_category_cnt = 0); i < ACL_FILTER_MAX_SRC_IP; i++) {
60	    src_ip_category_array[i].reset();
61	  }
62	  src_ip_valid = 0;
63	  for (i = (in_ip_cnt = 0); i < ACL_FILTER_MAX_IN_IP; i++) {
64	    in_ip_array[i].reset();
65	  }
66	  in_ip_valid = 0;
67	  internal    = 0;
68	}
