85	acl_filter_rule::add_argv(int _argc, char *_argv[])
86	{
87	  int real_cnt = 0;
88	  if (likely(_argv)) {
89	    for (int i = 0; i < _argc && argc < ACL_FILTER_MAX_ARGV; i++) {
90	      if (likely(_argv[i] && (argv[argc] = ats_strdup(_argv[i])) != nullptr)) {
91	        real_cnt++;
92	        argc++;
93	      }
94	    }
95	  }
96	  return real_cnt;
97	}
